engine_url_hint: "ऐप जहाँ ps5upload-engine तक पहुँचता है। डिफ़ॉल्ट स्थानीय sidecar पर छोड़ें, या किसी दूरस्थ/स्वयं-होस्ट किए इंजन पर इंगित करें। स्थानीय और दूरस्थ के बीच बदलने के बाद ऐप पुनः आरंभ करें।",
err_fs_read_path_not_allowed: "यह फ़ाइल केवल-पठन सिस्टम विभाजन में है जो सामान्यतः अवरुद्ध रहता है। /system, /system_data और अन्य संरक्षित पथों से पढ़ने के लिए सेटिंग्स → “सिस्टम फ़ाइलें डाउनलोड करने दें” चालू करें। यह केवल डाउनलोड को प्रभावित करता है — वहाँ हटाना, स्थानांतरित करना और लिखना कभी अनुमत नहीं है।",
err_rar_open_failed: "यह RAR संग्रह नहीं पढ़ा जा सका। यदि यह बहु-भाग सेट है, तो पहला भाग चुनें (…part1.rar / …part01.rar / ….rar) और सुनिश्चित करें कि सभी खंड एक ही फ़ोल्डर में हों। यदि पासवर्ड-सुरक्षित है, तो पासवर्ड दर्ज करें।",
err_rar_password_required: "यह RAR संग्रह पासवर्ड-सुरक्षित है। इसकी सामग्री पढ़ने और अपलोड करने के लिए नीचे पासवर्ड दर्ज करें।",
