fs_install_confirm_body_usb: "यह पैकेज को आंतरिक भंडारण में रखता है (कंसोल सीधे USB से इंस्टॉल नहीं कर सकता), इंस्टॉल करता है, फिर अस्थायी प्रति हटा देता है। आपकी ड्राइव की मूल फ़ाइल अछूती रहती है।",
