about_disclaimer_title: "अस्वीकरण",
about_disclaimer_purpose: "ps5upload केवल शोध, शिक्षा, अंतरसंचालनीयता और होमब्रू विकास के उद्देश्यों के लिए उपलब्ध कराया गया है। यह Sony Interactive Entertainment Inc. से संबद्ध, अनुमोदित या जुड़ा हुआ नहीं है। “PlayStation” और “PS5”, Sony Interactive Entertainment Inc. के ट्रेडमार्क हैं, जिनका उपयोग यहाँ केवल पहचान के लिए किया गया है।",
about_disclaimer_piracy: "इसका उपयोग केवल अपने स्वामित्व वाले हार्डवेयर और वैध रूप से अपने स्वामित्व वाली सामग्री के साथ करें। इसका उपयोग ऐसे सॉफ़्टवेयर की नकल करने, वितरित करने या चलाने के लिए नहीं किया जाना चाहिए जिसका उपयोग करने का आपको अधिकार नहीं है।",
about_disclaimer_risk: "यह सॉफ़्टवेयर “जैसा है” के आधार पर, बिना किसी प्रकार की वारंटी के प्रदान किया गया है। संशोधित कंसोल चलाने से वह स्थायी रूप से खराब हो सकता है, सेव और लाइसेंस अपरिवर्तनीय रूप से नष्ट हो सकते हैं, तथा आपका खाता या कंसोल प्रतिबंधित हो सकता है। आप इसका उपयोग पूर्णतः अपने जोखिम पर करते हैं और परिणामों की पूरी ज़िम्मेदारी स्वीकार करते हैं। शुरू करने से पहले वह सब कुछ बैकअप कर लें जिसे खोना आपके लिए संभव न हो।",
