"pkglib.installAll.whatBody": "“सभी इंस्टॉल करें” हर तैयार पैकेज को क्रम से चलाता है: बेस गेम → अपडेट → DLC। जब एक ही संस्करण के दो अपडेट हों (या दो परस्पर विरोधी DLC पैक हों), तो हर पंक्ति के चेकबॉक्स से चुनें कि यह कंसोल कौन-सा इंस्टॉल करे — प्रति समूह केवल एक। उस समूह को छोड़ने के लिए चेक हटा दें। किसी एक पंक्ति का इंस्टॉल बटन हमेशा केवल वही पैकेज इंस्टॉल करता है।",
