"library_mount_modal_rw_body": "इस तरह माउंट करने पर आप फ़ाइलें बदल सकते हैं, DLC जोड़ सकते हैं, या बैकपोर्ट पैच लगा सकते हैं — माउंट को संपादित करने के लिए फ़ाइल ब्राउज़र का उपयोग करें। बदलाव सीधे इमेज फ़ाइल में लिखे जाते हैं: गलत संपादन से गेम बूट नहीं होगा और इसे पूर्ववत नहीं किया जा सकता, इसलिए ज़रूरी हो तो पहले इमेज कॉपी कर लें। PS5 भी माउंट की गई इमेज में अपने-आप सेव डेटा लिख सकता है।",
