"pkg.reverify_impossible": "PS5 ने यह इंस्टॉल स्वीकार कर लिया, लेकिन ps5upload के पास इंस्टॉल हुए पैकेज को पहचानने का कोई तरीका नहीं है, इसलिए वह इसकी पुष्टि नहीं कर सकता। नतीजा PS5 की सूचनाओं में देखें। तैयार किया गया पैकेज रखा गया है।",
"pkg.reverify_gave_up": "30 मिनट बाद भी पुष्टि नहीं हुई। बहुत बड़े टाइटल में ज़्यादा समय लग सकता है — PS5 की सूचनाएँ देखें, या फिर से देखने के लिए फिर से जाँचें का उपयोग करें।",
