"backport_summary": "इससे गेम FW 4 SDK जोड़ी पर डाउनग्रेड होगा और {set} के साथ आने वाला {count}-लाइब्रेरी सेट इंस्टॉल होगा। सेट पूरा इंस्टॉल होता है — अलग-अलग गेम की लाइब्रेरी मिलाने से ही बैकपोर्ट लॉन्च होने में विफल होता है।",
"settings_card_fakelibs": "बैकपोर्ट लाइब्रेरी",
"backport_verify_unpatched": "यह टाइटल बैकपोर्ट नहीं है",
"backport_verify_unpatched_body": "इसके eboot में अब भी मूल SDK संस्करण है, इसलिए कोई भी लाइब्रेरी इंस्टॉल हो, यह इस फ़र्मवेयर पर नहीं चल सकता — समस्या लाइब्रेरी सेट में नहीं है। बैकपोर्ट फिर से चलाएँ; अगर ऐसा बार-बार हो, तो SDK पैच लग नहीं रहा है।",
"backport_no_larger": "इस गेम को ऐसी लाइब्रेरी चाहिए जो आपके किसी सेट में नहीं हैं। कोई ज़्यादा पूर्ण पैक आयात करें, या किसी दूसरे कंसोल को स्कैन करें।",
"backport_verifying": "चलाकर देख रहे हैं — विफल लॉन्च दोबारा आज़माया जाता है, क्योंकि लॉन्च इतना अविश्वसनीय है कि एक विफलता कुछ साबित नहीं करती।",
"backport_verify_running": "चल रहा है — क्या यह गेमप्ले तक पहुँचता है?",
"backport_verify_running_body": "एक मिनट बाद भी गेम चल रहा है ({threads} थ्रेड)। यानी यह लोड होते समय क्रैश नहीं हुआ, पर इसका मतलब यह नहीं कि यह खेलने लायक है — स्क्रीन देखें। काम करे तो रखें, नहीं तो पूर्ववत करके अगला सेट आज़माएँ।",
"backport_verify_missing": "इसे और लाइब्रेरी चाहिए",
"backport_verify_missing_body": "गेम ने ऐसा फ़ंक्शन बुलाया जो कोई भी इंस्टॉल की गई लाइब्रेरी नहीं देती। आज़माने के लिए {count} बड़े सेट बाकी हैं।",
"backport_verify_wrong": "इस गेम के लिए गलत लाइब्रेरी",
"backport_verify_wrong_body": "यह टाइटल सही ढंग से पैच है, पर इन लाइब्रेरी के साथ शुरू नहीं हुआ, इसलिए इसे यही लाइब्रेरी नहीं चाहिए। आज़माने के लिए {count} दूसरे सेट बाकी हैं।",
"backport_verify_unknown": "पता नहीं चल सका कि यह काम किया या नहीं",
"backport_verify_unknown_body": "लॉन्च के नतीजे मेल नहीं खाए, इसलिए इससे लाइब्रेरी के बारे में कुछ पता नहीं चलता — लॉन्च अपने-आप इतनी बार विफल होता है कि मिला-जुला नतीजा बेमानी है। इसे खुद चलाकर देखें, और खेलने लायक न हो तो पूर्ववत करें।",
"backport_get_more": "और लाइब्रेरी पाएँ…",
"backport_needs_libraries": "{name} का बैकपोर्ट करने के लिए बदली जाने वाली सिस्टम लाइब्रेरी चाहिए। ये Sony की फ़ाइलें हैं, इसलिए ps5upload इन्हें शामिल नहीं कर सकता — आप इन्हें एक बार अपने गेम से देते हैं, और हर बाद वाला बैकपोर्ट इन्हें दोबारा इस्तेमाल करता है।",
"fakelibs_action_failed": "वह काम नहीं किया",
"fakelibs_empty": "अभी कोई लाइब्रेरी नहीं। बैकपोर्ट के लिए बदली जाने वाली सिस्टम लाइब्रेरी चाहिए — Sony की फ़ाइलें जिन्हें ps5upload शामिल नहीं कर सकता, इसलिए आप इन्हें एक बार अपने गेम से देते हैं।",
