"joberr.ava1_refused": "PS5 ने यह अनुरोध अस्वीकार कर दिया (कोड {code})। फिर कोशिश करें; बार-बार हो तो हेल्पर और ऐप को एक ही संस्करण पर अपडेट करें और बग रिपोर्ट में यह कोड शामिल करें।",
"joberr.ava1_busy": "PS5 हेल्पर व्यस्त है और उसने यह ट्रांसफ़र समय पर स्वीकार नहीं किया। उसका दूसरा काम खत्म होने तक रुकें, फिर फिर कोशिश करें पर क्लिक करें।",
"joberr.ava1_unreachable": "PS5 तक पहुँचा नहीं जा सका। जाँचें कि वह चालू है, उसी नेटवर्क पर है और हेल्पर चल रहा है, फिर फिर कोशिश करें पर क्लिक करें।",
"joberr.ava1_exists": "गंतव्य PS5 पर पहले से मौजूद है। उसे बदलने के लिए अधिलेखित करें चुनें, या कोई दूसरा गंतव्य चुनें।",
"joberr.ava1_commit_exists": "फ़ाइल अपलोड हो गई लेकिन गंतव्य पहले से मौजूद होने के कारण प्रकाशित नहीं हो सकी। उसे बदलने के लिए अधिलेखित करें चुनें, या कोई दूसरा गंतव्य चुनें।",
"joberr.ava1_cross_device": "गंतव्य स्टेजिंग क्षेत्र से अलग ड्राइव पर है, इसलिए PS5 फ़ाइल को नहीं ले जा सका। उसी ड्राइव पर गंतव्य चुनें या पहले इंटरनल ड्राइव पर अपलोड करें।",
"joberr.ava1_wrong_console": "इस पते वाला डिवाइस वह PS5 नहीं है जिससे यह ऐप पेयर है। पता जाँचें, या इस कंसोल से फिर पेयर करें।",
"joberr.ava1_no_identity": "इस ऐप की अभी कोई पेयरिंग पहचान नहीं है। कनेक्शन स्क्रीन से PS5 के साथ पेयर करें और फिर कोशिश करें।",
"joberr.zip_read_error": ".zip पढ़ी नहीं जा सकी (पढ़ते समय फ़ाइल या उसकी ड्राइव हट गई हो सकती है)। जाँचें कि स्रोत अब भी जुड़ा है, फिर फिर कोशिश करें पर क्लिक करें।",
"joberr.ava1_zip_corrupt": "यह .zip पढ़ी नहीं जा सकी: यह क्षतिग्रस्त या अधूरी है। इसे दोबारा डाउनलोड या बनाएँ, फिर कोशिश करें।",
"joberr.ava1_7z_corrupt": "यह .7z पढ़ी नहीं जा सकी: यह क्षतिग्रस्त या अधूरी है। इसे दोबारा डाउनलोड या बनाएँ, फिर कोशिश करें।",
"joberr.ava1_7z_encrypted": "यह .7z एन्क्रिप्टेड है और स्ट्रीम नहीं हो सकती। इसे अपने कंप्यूटर पर एक्सट्रैक्ट करें और इसके बजाय फ़ोल्डर अपलोड करें।",
"joberr.ava1_7z_unsafe_path": "इस .7z में असुरक्षित फ़ाइल पाथ है (यह अपने फ़ोल्डर से बाहर जाता है)। इसे अपने कंप्यूटर पर एक्सट्रैक्ट करें और इसके बजाय फ़ोल्डर अपलोड करें।",
"joberr.rar_password": "इस .rar के लिए पासवर्ड चाहिए, या दिया गया पासवर्ड गलत था। सही पासवर्ड डालकर फिर कोशिश करें।",
"joberr.rar_corrupt": "यह .rar क्षतिग्रस्त है, या कुछ हिस्से गायब हैं या क्रम में नहीं हैं। सुनिश्चित करें कि सभी हिस्से मौजूद हैं, फिर कोशिश करें।",
"joberr.ava1_copy_lost": "PS5 इस कॉपी का पता खो बैठा (हेल्पर रीस्टार्ट हुआ या कनेक्शन टूटा)। इसे दोबारा शुरू करने के लिए फिर कोशिश करें पर क्लिक करें।",
"joberr.ava1_copy_failed": "PS5 कॉपी पूरी नहीं कर सका। खाली जगह जाँचें और यह भी कि स्रोत व गंतव्य अब भी उपलब्ध हैं, फिर कोशिश करें।",
"joberr.ava1_local_io": "यह कंप्यूटर डाउनलोड की गई फ़ाइल नहीं लिख सका। गंतव्य फ़ोल्डर की अनुमतियाँ और खाली जगह जाँचें, फिर कोशिश करें।",
"joberr.ava1_bad_manifest": "PS5 ने ऐसी फ़ाइल सूची भेजी जिसे यह ऐप समझ नहीं सका। हेल्पर और ऐप को एक ही संस्करण पर अपडेट करें, फिर कोशिश करें।",
"joberr.helper_not_ava1": "PS5 हेल्पर नहीं चल रहा। इसे कनेक्शन स्क्रीन से भेजें (बैनर सुझाए तो हेल्पर अपडेट करें का उपयोग करें), फिर कोशिश करें।",
"joberr.helper_not_ava1_web": "PS5 हेल्पर नहीं चल रहा। यह वेब UI इसे भेज नहीं सकता: अपने सामान्य पेलोड लोडर से कंसोल पर ps5upload पेलोड शुरू करें (बैनर सुझाए तो हेल्पर अपडेट करें का उपयोग करें), फिर कोशिश करें।",
"joberr.not_paired": "इस PS5 ने अभी तक यह ऐप स्वीकार नहीं किया है। दोनों को पेयर करें (पेयर करें… बटन), फिर कोशिश करें।",
