volumes_pkg_copies_hint: "यह विकल्प क्या करता है: “अपलोड और इंस्टॉल” पहले .pkg फ़ाइल को PS5 पर कॉपी करता है, फिर उसी प्रति से इंस्टॉल करता है। यह केवल तय करता है कि वे प्रतियाँ किस ड्राइव पर रहेंगी। गेम कहाँ इंस्टॉल होंगे यह नहीं बदलता (यह PS5 अपनी स्टोरेज सेटिंग में तय करता है), और “स्ट्रीम और इंस्टॉल” कोई प्रति नहीं रखता। चुनी गई ड्राइव जुड़ी न हो तो प्रतियाँ आंतरिक स्टोरेज में जाती हैं।",
saves_auto_folder_label: "बैकअप फ़ोल्डर",
captures: "स्क्रीनशॉट और क्लिप",
captures_title: "कैप्चर",
"arcpkg.choose": "आर्काइव चुनें…",
"arcpkg.help": "ऐसी .zip, .7z या .rar के लिए जिसके किसी भी फ़ोल्डर में एक या अधिक .pkg फ़ाइलें हों। केवल पैकेज निकाले जाते हैं, सीधे PS5 पर (इस कंप्यूटर पर कुछ नहीं निकाला जाता), फिर एक-एक करके इंस्टॉल होते हैं: पहले मूल गेम, फिर उसका अपडेट, फिर DLC। कई हिस्सों वाली RAR (.part1.rar, .part2.rar…) समर्थित है: पहला हिस्सा चुनें और बाकी उसके साथ रखें। RAR को पासवर्ड चाहिए तो पूछा जाता है; पासवर्ड वाली ZIP और 7z समर्थित नहीं हैं।",
"arcpkg.keepsRunning": "आप कोई दूसरी स्क्रीन खोलें तब भी यह चलता रहता है, और «कार्य» में भी दिखता है।",
"arcpkg.notArchive": "यह फ़ाइल .zip, .7z या .rar आर्काइव नहीं है।",
"arcpkg.pick": "कोई आर्काइव चुनें",
"arcpkg.title": "आर्काइव से पैकेज इंस्टॉल करें",
"install.library.title": "PS5 पर पैकेज की प्रतियाँ",
"install.stream.file.help": "कोई .pkg या .fpkg चुनें, या उसे इस विंडो पर कहीं भी छोड़ें। इंस्टॉल पूरा होने तक ऐप खुला रखें; प्रगति ऊपर की कतार में और «कार्य» में दिखती है।",
"install.stream.file.title": "पैकेज फ़ाइल इंस्टॉल करें",
"install.tab.stream.lead": "PS5 सीधे इस कंप्यूटर से या किसी लिंक से इंस्टॉल करता है। पहले PS5 पर कोई प्रति नहीं रखी जाती, इसलिए वहाँ खाली जगह नहीं चाहिए, और यह इंस्टॉल करने का सबसे भरोसेमंद तरीका है।",
"install.tab.upload.lead": "पैकेज पहले PS5 पर कॉपी होता है, फिर उसी प्रति से इंस्टॉल होता है। इसे तब इस्तेमाल करें जब PS5 इस कंप्यूटर तक नहीं पहुँच पाता (स्ट्रीम नेटवर्क त्रुटि से विफल होती है), या जब आप पैकेज PS5 पर रखकर बाद में इस कंप्यूटर के बिना दोबारा इंस्टॉल करना चाहें।",
"install.upload.file.browser": "यहाँ से PS5 पर पैकेज कॉपी करने के लिए डेस्कटॉप ऐप चाहिए। वेब UI में «स्ट्रीम और इंस्टॉल» इस्तेमाल करें, या नीचे वे पैकेज इंस्टॉल करें जो पहले से PS5 पर हैं।",
"install.upload.file.help": "कोई .pkg या .fpkg चुनें। प्रति के लिए PS5 पर पूरे पैकेज जितनी खाली जगह चाहिए, और जब तक आप उसे हटाते नहीं वह नीचे की सूची में रहती है।",
"install.upload.file.title": "पैकेज PS5 पर कॉपी करें और इंस्टॉल करें",
"linkcard.confirm.direct": "PS5 खुद लिंक से पैकेज डाउनलोड करके इंस्टॉल करता है। शुरू होने के बाद इस कंप्यूटर की ज़रूरत नहीं रहती, और प्रगति यहाँ नहीं, PS5 पर (डाउनलोड) दिखती है। अगर PS5 लिंक तक नहीं पहुँच पाता, तो ऐप उसे इस कंप्यूटर के ज़रिए भेजता है। पहले से इंस्टॉल गेम के ऊपर दोबारा इंस्टॉल करने पर, Sony का इंस्टॉलर विफल हो तो वह गेम हट सकता है। केवल उन्हीं पैकेजों के लिंक इस्तेमाल करें जिन पर आपको भरोसा है और जिन्हें इंस्टॉल करने का आपको अधिकार है।",
"linkcard.confirm.download": "यह कंप्यूटर पहले पूरा पैकेज डिस्क पर सहेजता है, फिर उसे PS5 पर इंस्टॉल करता है। दोनों चरण पूरे होने तक इसे चालू रहना चाहिए, और पैकेज के लिए खाली जगह चाहिए। पहले से इंस्टॉल गेम के ऊपर दोबारा इंस्टॉल करने पर, Sony का इंस्टॉलर विफल हो तो वह गेम हट सकता है। केवल उन्हीं पैकेजों के लिंक इस्तेमाल करें जिन पर आपको भरोसा है और जिन्हें इंस्टॉल करने का आपको अधिकार है।",
"linkcard.confirm.stream": "यह कंप्यूटर पैकेज डाउनलोड करके तुरंत PS5 को देता जाता है, इसलिए इंस्टॉल पूरा होने तक इसे चालू और जुड़ा रहना चाहिए। डिस्क पर कुछ नहीं सहेजा जाता। पहले से इंस्टॉल गेम के ऊपर दोबारा इंस्टॉल करने पर, Sony का इंस्टॉलर विफल हो तो वह गेम हट सकता है। केवल उन्हीं पैकेजों के लिंक इस्तेमाल करें जिन पर आपको भरोसा है और जिन्हें इंस्टॉल करने का आपको अधिकार है।",
