stop: "रोकें",
activity_description_v2: "ऐप आपके कंसोल पर जो कुछ कर रहा है और कर चुका है: अपलोड, डाउनलोड, इंस्टॉल और फ़ाइल कार्य। यहाँ से किसी को भी रोकें या दोबारा आज़माएँ। सबसे हाल के 100 रखे जाते हैं, रीस्टार्ट के बाद भी।",
fw_spoof_subtitle_v2: "जाँचता है कि इस PS5 द्वारा बताया गया फ़र्मवेयर संस्करण किसी स्पूफ़ पेलोड ने बदला है या नहीं, ताकि उस पर निर्भर कुछ इंस्टॉल करने से पहले आपको असली संस्करण पता हो।",
health_subtitle_v2: "जाँचता है कि PS5, यह ऐप और उनके बीच का नेटवर्क काम कर रहे हैं, न कर रहे हों तो बताता है कि क्या ठीक करना है, और उनके बीच फ़ाइल ट्रांसफ़र की गति मापता है।",
remotePlay_subtitle_v2: "इस PS5 को रिमोट प्ले के लिए सेट करें और वह PIN पाएँ जो PS Remote Play ऐप को इससे जोड़ता है।",
saves_description_v2: "PS5 पर सेव डेटा, हर गेम के लिए एक प्रविष्टि। किसी गेम के सेव का बैकअप इस कंप्यूटर पर .zip में लें, और बाद में उसे पुनर्स्थापित करें।",
shell_description_v2: "ऐसे कमांड टाइप करें जो PS5 पर हेल्पर प्रोसेस के अंदर चलते हैं। उन्नत उपयोगकर्ताओं के लिए। आउटपुट प्रति कमांड 256 KB तक सीमित है; ऊपर और नीचे के तीर पिछले कमांड वापस लाते हैं।",
"arcpkg.links.go": "{count} फ़ाइलें डाउनलोड करें",
"arcpkg.links.help": "आर्काइव का, या बँटे हुए आर्काइव के हर हिस्से का सीधा लिंक चिपकाएँ, हर पंक्ति में एक। फ़ाइलें इस कंप्यूटर (Downloads/ps5upload) पर डाउनलोड होती हैं, जहाँ उन सबके लिए जगह चाहिए; फिर उनके अंदर के पैकेज ऊपर बताए अनुसार PS5 पर निकाले जाते हैं।",
