"arcpkg.noFirstPart": "फ़ाइलें डाउनलोड हो गईं, पर उनमें से कोई भी किसी आर्काइव का पहला हिस्सा नहीं है (.zip, .7z, .rar या .part1.rar)। लिंक जाँचें।",
"fpkg.image.done": "गेम इमेज लिखी गई और वापस पढ़कर जाँची गई। इसे PS5 की ड्राइव पर कॉपी करें («अपलोड») और ShadowMount+ इसे माउंट कर देगा।",
"fpkg.image.what": "एक फ़ाइल जिसे आप PS5 ड्राइव पर कॉपी करते हैं, जिसे ShadowMount+ माउंट करके होम स्क्रीन पर दिखाता है। कुछ भी इंस्टॉल नहीं होता।",
