connection_payload_engine_unreachable: "ऐप इस कंप्यूटर पर अपने ही इंजन तक नहीं पहुँच पाया, इसलिए उसे नहीं पता कि PS5 पर हेल्पर शुरू हुआ या नहीं। यह PS5 की समस्या नहीं है: विंडो के ऊपर का नोटिस कारण बताता है और इंजन को फिर से शुरू कर सकता है। फिर «हेल्पर भेजें» दोबारा दबाएँ। ({error})",
"engine_problem.missing.fix": "ps5upload-engine को अपने एंटीवायरस के क्वारंटीन से वापस लाएँ (या अनुमति दें), या ऐप दोबारा इंस्टॉल करें।",
"engine_problem.missing.why": "इंजन प्रोग्राम ऐप के फ़ोल्डर में नहीं है। सुरक्षा सॉफ़्टवेयर कभी-कभी इसे क्वारंटीन कर देता है।",
"engine_problem.port.fix": "«इंजन फिर से शुरू करें» दबाएँ। अगर काम न बने, तो फ़ायरवॉल या एंटीवायरस में ps5upload-engine को अनुमति दें, फिर ऐप फिर से शुरू करें।",
"engine_problem.port.why": "कोई चीज़ इंजन का पता ({url}) घेरे हुए है पर जवाब नहीं देती: उस पोर्ट पर कोई दूसरा प्रोग्राम, या उससे कनेक्शन रोकने वाला सुरक्षा सॉफ़्टवेयर।",
"engine_problem.proxy.fix": "लोकल पतों (127.0.0.1) के लिए प्रॉक्सी या VPN टूल बंद करें, या ऐप को http_proxy / ALL_PROXY सेटिंग के बिना शुरू करें।",
"engine_problem.proxy.why": "इंजन के लिए अनुरोध इंजन के बजाय इस कंप्यूटर पर सेट किए गए प्रॉक्सी पर चले गए।",
"engine_problem.remote.fix": "जाँचें कि इंजन (Docker कंटेनर या दूसरा कंप्यूटर) चल रहा है और उस पते पर पहुँच योग्य है, या «सेटिंग्स» में पता बदलें।",
"engine_problem.remote.why": "यह ऐप जिस इंजन ({url}) को इस्तेमाल करने के लिए सेट है, वह जवाब नहीं देता।",
"engine_problem.restart": "इंजन फिर से शुरू करें",
"engine_problem.slow.fix": "«इंजन फिर से शुरू करें» दबाएँ। लोकल कनेक्शन फ़िल्टर करने वाला फ़ायरवॉल या एंटीवायरस भी इसका कारण हो सकता है: ps5upload-engine को अनुमति दें।",
"engine_problem.slow.why": "इंजन चल रहा है पर जवाब नहीं देता।",
"engine_problem.stopped.fix": "«इंजन फिर से शुरू करें» दबाएँ। अगर यह फिर रुके, तो «लॉग» स्क्रीन कारण दिखाती है।",
"engine_problem.stopped.why": "इंजन नहीं चल रहा: यह रुक गया, या कभी शुरू ही नहीं हुआ।",
"engine_problem.title": "ऐप इस कंप्यूटर पर अपने इंजन तक नहीं पहुँच पा रहा",
"engine_problem.web.fix": "जाँचें कि सर्वर (Docker कंटेनर) चल रहा है, फिर यह पेज दोबारा लोड करें।",
"engine_problem.web.why": "इस पेज का उस ps5upload सर्वर से कनेक्शन टूट गया जहाँ से यह आया था।",
gate_engine_down_body_v2: "इस स्क्रीन को ऐप का इंजन चाहिए, जो जवाब नहीं दे रहा। विंडो के ऊपर का नोटिस कारण बताता है और उसे फिर से शुरू कर सकता है।",
"profile.np.body": "Sony से संपर्क किए बिना, PS5 साइन-इन खाते को PlayStation Network में साइन इन मानने लगता है। कंसोल की कुछ सुविधाएँ केवल साइन-इन खाते के लिए खुलती हैं, उनमें रिमोट प्ले भी है। इसमें earthonion का np-fake-signin इस्तेमाल होता है, जो बटन दबाने पर उसके प्रोजेक्ट पेज से लाया जाता है।",
"profile.np.confirm_title": "इस खाते को साइन इन करें?",
"profile.np.failed": "साइन-इन नहीं चला",
"profile.np.fetching": "np-fake-signin लाया जा रहा है…",
"profile.np.sending": "PS5 को भेजा जा रहा है…",
"profile.np.sent": "np-fake-signin {version} PS5 पर चल गया। पूरा करने के लिए PS5 फिर से शुरू करें; इसके बाद खाता साइन इन दिखेगा, और सेटिंग्स > सिस्टम > रिमोट प्ले चालू किया जा सकेगा।",
"profile.np.sign_in": "साइन इन",
"profile.np.state_loading": "खाता पढ़ा जा रहा है…",
"profile.np.state_no_slot": "ऊपर कोई खाता {user} नाम का नहीं है, इसलिए np-fake-signin रुक जाएगा। खाते को वही नाम दें जो साइन-इन उपयोगकर्ता का है, या उसके लिए एक खाता सक्रिय करें।",
"profile.np.state_no_user": "PS5 पर कोई उपयोगकर्ता साइन इन नहीं है। जिस प्रोफ़ाइल को चाहते हैं उसमें साइन इन करें, फिर वापस आएँ।",
"profile.np.state_not_activated": "{user} (खाता {slot}) के पास अभी खाता ID नहीं है। पहले इसे ऊपर «खाते» में सक्रिय करें।",
"profile.np.state_ready": "तैयार: {user} (खाता {slot}) सक्रिय है।",
"profile.np.step_activate": "खाते को खाता ID चाहिए। PSN से जुड़े खाते के पास यह होती है; नहीं तो इसे ऊपर «खाते» में सक्रिय करें (ऑफ़लाइन सक्रियण)।",
"profile.np.step_run": "PS5 पर उस उपयोगकर्ता के साइन इन रहते «साइन इन» दबाएँ। यह एक बार चलकर बंद हो जाता है।",
"profile.np.title": "PlayStation Network में साइन इन (ऑफ़लाइन)",
