"fpkg.image.make_compressed": "संपीड़ित इमेज बनाएँ",
"fpkg.image.compress_body_v2": "आम तौर पर 40–60% छोटी, बनने में ज़्यादा समय लेती है और हमेशा केवल-पढ़ने के लिए माउंट होती है। यह लिखते समय ही संपीड़ित होती है, इसलिए डिस्क पर केवल संपीड़ित फ़ाइल रहती है।",
"fpkg.image.level_fast_body": "बनाने में सबसे तेज़, थोड़ा बड़ा।",
"fpkg.image.level_balanced_body": "लगभग उतना ही छोटा, और बनाने में कई गुना तेज़।",
"fpkg.image.level_smallest_body": "सबसे छोटी फ़ाइल: हर ब्लॉक पर एक दूसरा, ज़्यादा मज़बूत एन्कोडर चलता है, इसलिए कई गुना ज़्यादा समय लगता है।",
"fpkg.image.ffpfs": ".ffpfs (PFS), प्रायोगिक",
"fpkg.image.ffpfs_body": "ShadowMount+ 1.7 में प्रायोगिक। फ़ाइल नाम केवल ASCII होने चाहिए; इमेज का अपना नाम 63 अक्षरों तक सीमित रखा जाता है।",
