"collection.serving_body_v2": "वे पैकेज जो यह कंप्यूटर उस PS5 को परोस रहा है जो उन्हें ख़ुद लेता है। लिंक उसी PS5 के लिए काम करता है जिसके लिए बना है (या अनुमति देने पर नेटवर्क के किसी भी डिवाइस के लिए), जब तक आप इसे रोकें नहीं या ऐप बंद न हो।",
