"collection.permanent_delete": "कॉपियों को हमेशा के लिए हटाने दें",
"collection.permanent_delete_hint": "इस इंजन में कोई ट्रैश नहीं है (Docker या बिना डेस्कटॉप वाला सर्वर)। इसे चालू करने पर संग्रह से कॉपी हटाई जा सकती है: वह हमेशा के लिए चली जाती है, और हर बार आप पुष्टि करते हैं।",
"collection.trash_unavailable_v2": "इस इंजन में कोई ट्रैश नहीं है। यहाँ से कॉपियाँ हटाने के लिए, संग्रह → फ़ोल्डर में \"कॉपियों को हमेशा के लिए हटाने दें\" चालू करें।",
"pkg.sony_80b21104": "PS5 ने यह पैकेज स्वीकार नहीं किया (0x80B21104)। अगर इस कंसोल पर दूसरे पैकेज इंस्टॉल होते हैं, तो समस्या इसी फ़ाइल में है: ज़्यादातर किसी नए गेम का पैकेज जो उन टूल्स से बना है जिन्हें इस कंसोल का फ़र्मवेयर नहीं समझता, या ऐसा पैकेज जो नकली-हस्ताक्षरित (FPKG) बिल्ड नहीं है। अपने फ़र्मवेयर के लिए बना पैकेज (बैकपोर्ट) इस्तेमाल करें, या गेम को इंस्टॉलर के बिना इंस्टॉल करें: अपलोड से उसका गेम फ़ोल्डर, या ShadowMount+ के लिए गेम इमेज (.exfat या .ffpfsc) कॉपी करें।",
"fpkg.imageQueued": "अपलोड कतार में है: आगे यह PS5 पर उस फ़ोल्डर में जाएगा जिस पर ShadowMount+ नज़र रखता है।",
