drive_subtitle: "एक फ़ोल्डर जो आपके कंप्यूटर, फ़ोन और Docker पर एक जैसा रहता है, और जिसका मूल स्थान यह कंसोल है। कहीं भी फ़ाइल जोड़ें और वह ड्राइव के हर डिवाइस तक पहुँचती है।",
drive_need_console: "मेश ड्राइव इस्तेमाल करने के लिए किसी कंसोल से कनेक्ट करें",
drive_how: "यह कैसे काम करता है",
drive_how_1: "जब तक कंसोल का हेल्पर चलता है, ड्राइव का हर डिवाइस हर आधे मिनट में कंसोल पर मूल फ़ोल्डर से सिंक होता है। Docker बिना ऐप खोले चलता रहता है।",
drive_how_2: "एक साथ दो जगह बदली गई: दोनों रखी जाती हैं, एक का नाम \"(… से टकराव)\" कर दिया जाता है।",
drive_how_3: "मिटाई गई फ़ाइलें 30 दिन के लिए ड्राइव के .ps5upload-trash फ़ोल्डर में जाती हैं। एक साथ बहुत सी फ़ाइलें मिटाने पर आपकी पुष्टि का इंतज़ार होता है।",
drive_how_4: "जिस फ़ोल्डर में उसकी .ps5upload-mesh फ़ाइल नहीं है (निकाली गई ड्राइव), उसे ऑफ़लाइन माना जाता है, मिटाया हुआ कभी नहीं।",
drive_join_body: "इस डिवाइस पर वह फ़ोल्डर चुनें जिसमें ड्राइव रहेगी। उसमें पहले से मौजूद फ़ाइलें ड्राइव में जुड़ जाती हैं; ड्राइव की फ़ाइलें यहाँ आ जाती हैं।",
drive_how_5: "कोई भी डिवाइस इस टैब से जुड़ सकता है। दूसरों को रोकने के लिए ड्राइव पर पासवर्ड लगाएँ; कंसोल पर सिर्फ़ उसका हैश रखा जाता है।",
