keep_ps5_awake_mode_hint_v2: "PS5 के ऑटो-स्टैंडबाय टाइमर को समय-समय पर रीसेट करता है ताकि वह रेस्ट मोड में न जाए। “अपलोड और इंस्टॉल के दौरान” लंबे अपलोड को बचाता है (विफल अपलोड का एक आम कारण; डिफ़ॉल्ट)। “कनेक्टेड रहते हमेशा” ऐप खुला रहने तक चल रहे हेल्पर वाले हर कंसोल को रेस्ट मोड से बाहर रखता है। PS5 को हाथ से रेस्ट मोड में डालना हर मोड में काम करता है।",
kernellog_categories_explainer: "हर श्रेणी शुरुआत में दिखाई जाती है। Sony वाली श्रेणियाँ कंसोल के अपने सबसिस्टम हैं, जो हर जेलब्रोकन PS5 पर, कोई भी पेलोड चल रहा हो, लगातार लॉग करती हैं; ये ps5upload की वजह से नहीं हैं। शोर कम करने के लिए इन्हें अनचेक करें।",
