payloads_description_catalog_v2: "चुने हुए थर्ड-पार्टी PS5 होमब्रू पेलोड। नवीनतम रिलीज़ जाँचें, एक बार डाउनलोड करें, फिर एक क्लिक में अपने PS5 पर भेजें। संस्करण लोकल कैश होते हैं ताकि आप उन्हें USB पेलोड स्टिक पर भी रख सकें।",
payloads_description_send_v2: "कोई भी PS5 पेलोड फ़ाइल — .elf, .bin, .js, .lua या .jar (kstuff, कस्टम होमब्रू लोडर, ब्राउज़र-स्टेज एक्सप्लॉइट, प्लगइन स्क्रिप्ट, BD-JB JAR) — अपने PS5 पर भेजें। कनेक्शन स्क्रीन जैसा ही तरीका, बस आपकी चुनी फ़ाइल के साथ। पोर्ट फ़ाइल प्रकार के अनुसार होता है (.elf/.bin 9021, .jar 9025, .lua 9026, .js 50000); इसे तभी बदलें जब आपका लोडर कहीं और सुनता हो।",
payloads_download_failed: "डाउनलोड विफल: {id}",
