payloads_sent_body: "पेलोड v{version} :9021 पर लोडर को भेजा गया। इसकी सूचना के लिए PS5 देखें।",
payloads_sent_body_pm: "पोर्ट 9021 ने जवाब नहीं दिया, इसलिए पेलोड v{version} इसके बजाय Payload Manager (:8084) से लॉन्च किया गया। इसकी सूचना के लिए PS5 देखें।",
