peripheral_drive_attachable: "इस मॉडल में बिल्ट-इन डिस्क ड्राइव नहीं है; ये केवल ऐड-ऑन ड्राइव लगी होने पर ही कुछ करते हैं।",
power_telemetry_title_v2: "आजीवन काउंटर",
processes_kill_payload_body: "यह पेलोड “{name}” (kstuff, etaHEN आदि) को बंद कर देता है। जो कुछ यह देता है वह तब तक रुका रहता है जब तक आप इसे फिर से नहीं भेजते, और जिन गेम को इसकी ज़रूरत है वे शुरू होना बंद कर सकते हैं।",
