"profile.np.browser_v2": "साइन इन के लिए डेस्कटॉप ऐप चाहिए: यह np-fake-signin लाकर PS5 पर भेजता है, जो वेब UI नहीं कर सकता।",
ps5notif_empty_hint_v2: "जब ps5upload आपके TV पर कोई संदेश दिखाता है, जैसे रिमोट प्ले PIN या कोई चीट चालू होना, तो वह यहाँ दिखता है ताकि आप उसे फिर से पढ़ सकें। यह PS5 का अपना सूचना पैनल नहीं है; कंसोल हमें उसे पढ़ने नहीं देता।",
reset_confirm_body_browser: "यह ब्राउज़र PS5Upload के लिए जो भी सेटिंग और सेव की गई स्थिति रखता है, वह सब साफ़ करता है, और पेज नए सिरे से लोड होता है। सर्वर पर इंजन का अपना डेटा (कंसोल पेयरिंग, संग्रह, सेव किए सर्वर, बैकपोर्ट लाइब्रेरी, इंस्टॉल इतिहास, लॉग) नहीं छुआ जाता, और न ही आपके PS5 पर कुछ। इसे पूर्ववत नहीं किया जा सकता।",
reset_confirm_body_v2: "यह PS5Upload का सारा लोकल डेटा स्थायी रूप से मिटा देता है: सेटिंग्स, आपके सेव किए PS5 और उनकी पेयरिंग, संग्रह, सेव किए सर्वर और उनके पासवर्ड, बैकपोर्ट लाइब्रेरी, इंस्टॉल इतिहास, जॉब और इवेंट, गतिविधि/कतार इतिहास, लॉग, पेलोड कैश और क्रैश रिपोर्ट। यह आपके PS5 पर कुछ भी नहीं छूता। ऐप नई स्थिति में फिर से लोड होता है। इसे पूर्ववत नहीं किया जा सकता।",
reset_hint_browser: "यह ब्राउज़र PS5Upload के लिए जो भी सेटिंग और सेव की गई स्थिति रखता है, उसे साफ़ करके फिर से शुरू करें। इंजन अपने सर्वर पर जो रखता है (कंसोल पेयरिंग, संग्रह, सेव किए सर्वर, बैकपोर्ट लाइब्रेरी, इंस्टॉल इतिहास, लॉग) वह नहीं छुआ जाता, और आपके PS5 पर कुछ भी प्रभावित नहीं होता।",
reset_hint_v2: "PS5Upload का हर लोकल निशान मिटाकर फिर से शुरू करें: सेटिंग्स, सेव किए PS5 और उनकी पेयरिंग, संग्रह, सेव किए सर्वर और उनके पासवर्ड, बैकपोर्ट लाइब्रेरी, इंस्टॉल इतिहास, जॉब और इवेंट, गतिविधि/कतार इतिहास, लॉग, पेलोड कैश और क्रैश रिपोर्ट। आपके PS5 पर कुछ भी प्रभावित नहीं होता। ऊपर का बैकअप / रीस्टोर पेयरिंग, संग्रह, सर्वर पासवर्ड या बैकपोर्ट लाइब्रेरी को कवर नहीं करता।",
saves_backup_usb_tooltip_v2: "इस सेव को सेटिंग्स में सेट किए सेव पाथ पर ड्राइव (PS5 पर एक USB ड्राइव) में zip करें। यह इस कंप्यूटर पर कॉपी, zip और वापस भेजा जाता है, इसलिए ऐप खुला रखें; यहाँ की कॉपी बाद में हटा दी जाती है।",
saves_description_browser: "PS5 पर सेव डेटा, हर गेम के लिए एक प्रविष्टि। सेव का .zip में बैकअप लेने और रीस्टोर करने के लिए डेस्कटॉप ऐप चाहिए; यहाँ आप उन्हें देख सकते हैं और उनके फ़ोल्डर खोल सकते हैं।",
saves_restore_usb_tooltip_v2: "सेटिंग्स में सेट किए सेव पाथ पर इसके नवीनतम बैकअप से यह सेव रीस्टोर करें। zip इस कंप्यूटर पर कॉपी, अनपैक और PS5 पर वापस भेजा जाता है, इसलिए ऐप खुला रखें। मौजूदा सेव को ओवरराइट करता है।",
