upload_auto_resume_hint_browser: "अगर ट्रांसफ़र के बीच अपलोड टूट जाए, तो PS5 का हेल्पर फिर से जवाब देते ही जहाँ रुका था वहीं से फिर शुरू करें, हार मानने से पहले कुछ बार फिर कोशिश करते हुए। यह पेज हेल्पर को ख़ुद दोबारा नहीं भेज सकता: अगर PS5 रीस्टार्ट हुआ है, तो पहले उसे फिर से भेजें। PS5 की जगह खत्म होने जैसी गंभीर समस्याओं पर तुरंत रुकता है। डिफ़ॉल्ट रूप से चालू।",
upload_wake_for_uploads: "इंतज़ार कर रहे अपलोड के लिए PS5 जगाएँ",
upload_wake_for_uploads_hint: "जब कोई अपलोड रेस्ट मोड में पड़े PS5 का इंतज़ार कर रहा हो, तो उसे जगाने का सिग्नल भेजें और हेल्पर वापस आते ही आगे बढ़ें। केवल उन कंसोल के लिए जिनमें कनेक्शन स्क्रीन पर जगाना सेट है। डिफ़ॉल्ट रूप से चालू।",
upload_picker_from_ps5_hint: "किसी दूसरे PS5 से कॉपी कर रहे हैं? फ़ाइल सिस्टम में फ़ाइलें चुनें और दूसरे कंसोल पर भेजें चुनें।",
