install_hint_setup_exe: "इंस्टॉलर खुल गया है: उसके निर्देशों का पालन करें, और वह PS5Upload को उसी जगह अपडेट कर देगा।",
install_path_fallback_hint: "उस पैकेज के लिए आख़िरी उपाय जो पहले से PS5 पर है, जब PS5 उसे अपने स्टोरेज से भी मना कर दे और इस कंप्यूटर से भी न ला सके। केवल उस बेस गेम के लिए इस्तेमाल होता है जो इंस्टॉल नहीं है, इसलिए यह कुछ भी नहीं हटा सकता। अप्रमाणित: फ़र्मवेयर 11.20 पर यह काम कर चुका है और 13.60 पर मना हुआ है। अगर आप इसे आज़माते हैं, तो कृपया बताएँ कि यह काम किया या नहीं।",
install_path_fallback_label: "जब PS5 इस कंप्यूटर तक न पहुँच सके तो फ़ाइल पथ से इंस्टॉल करें",
"installed_fix_permissions": "अनुमतियाँ ठीक करें: इस गेम का फ़ोल्डर PS5 के लिए पढ़ने और चलाने योग्य बनाएँ (chmod 777)",
"installed_fix_permissions_done": "अनुमतियाँ ठीक कर दी गईं: इस गेम के फ़ोल्डर की हर फ़ाइल अब 0777 है। चलाएँ दबाएँ।",
"installed_fix_permissions_short": "अनुमतियाँ ठीक करें",
"installed_launch_homebrew_refused": "PS5 ने यह गेम शुरू करने से मना कर दिया (0x80940033)। कंसोल अभी homebrew या नकली-पैकेज गेम शुरू नहीं कर रहा है: kstuff दोबारा लोड करें (या रीबूट करके फिर से जेलब्रेक चलाएँ), फिर दोबारा चलाएँ दबाएँ।",
"installed_launch_no_kstuff": "PS5 ने यह गेम शुरू करने से मना कर दिया (0x80940033) क्योंकि kstuff नहीं चल रहा है। इसके बिना कंसोल कोई homebrew या नकली-पैकेज गेम शुरू नहीं करता। kstuff लोड करें (आपका autoloader, या कनेक्शन → सेट करें) और दोबारा चलाएँ दबाएँ।",
