"minion_remove_note": "हटाने पर Minion बंद हो जाता है और PS5 पर उसका रखा हुआ सब कुछ मिट जाता है: फ़ाइलें के उसके पसंदीदा और हाल के फ़ोल्डर, उसका गेम लाइब्रेरी कैश और उसका कंट्रोलर लॉग। नेटवर्क शेयर, चीट और बैकअप बने रहते हैं; PC ऐप भी इनका उपयोग करता है।",
"minion_remove": "इस PS5 से Minion हटाएँ…",
