"minion_remove_confirm": "इसकी होम-स्क्रीन टाइल और पेज हट जाएँगे, और PS5 पर इसकी अपनी फ़ाइलें मिट जाएँगी। हेल्पर इसे अब से बंद रखेगा। आप यहाँ कभी भी इसे फिर से चालू कर सकते हैं।",
