"minion_removed_done": "Minion हटा दिया गया: इसकी टाइल और पेज हट गए हैं और PS5 पर इसकी {n} फ़ाइलें मिटा दी गईं। हेल्पर के पुनः आरंभ होने के बाद भी यह बंद रहेगा, जब तक आप इसे यहाँ चालू नहीं करते।",
"fs_dragout_n_items": "{n} आइटम",
"fs_dragout_over_cap": "एक बार खींचने पर 4 GB तक आता है। अधिक के लिए, राइट-क्लिक → डाउनलोड करें।",
"fs_drag_hint_move": "फ़ाइलों और फ़ोल्डरों को इस कंप्यूटर पर कॉपी करने के लिए विंडो से बाहर खींचें, या यहाँ कॉपी करने के लिए अंदर खींचें। उन्हें यहाँ के किसी फ़ोल्डर में ले जाने के लिए खींचते समय Alt (Mac पर ⌥ Option) दबाए रखें।",
"fs_drag_hint": "फ़ाइलों और फ़ोल्डरों को इस कंप्यूटर पर कॉपी करने के लिए विंडो से बाहर खींचें, या यहाँ कॉपी करने के लिए अंदर खींचें।",
