"pm_add_hint": "Payload Manager फ़ाइल को PS5 पर रखता है, उसे यहाँ से या बूट पर चलाता है, और अपने मेन्यू में दिखाता है। कैटलॉग से सेव किया गया पेलोड, कैटलॉग में नई रिलीज़ आने पर यहाँ दिखाया जाता है।",
