"ps4move_safety": "PS4 सिर्फ़ पढ़ा जाता है, कभी बदला नहीं जाता। उसके सेव पहले इस कंप्यूटर पर कॉपी होते हैं। PS5 पर सिर्फ़ चुने गए गेम छुए जाते हैं, हर एक का सेव बदलने से पहले बैकअप होता है, और कुछ और (यूज़र, सिस्टम फ़ाइलें, ट्रॉफ़ी) नहीं बदलता।",
