"upload_as_image_desc_v2": "हज़ारों फ़ाइलों के बजाय एक इमेज फ़ाइल, जिसे ShadowMount+ माउंट करता है: भेजने में कहीं तेज़, और संपीड़ित होकर PS5 पर कम जगह लेती है। इमेज पहले इसी कंप्यूटर पर बनती है (इसके लिए यहाँ जगह चाहिए), फिर नीचे के फ़ोल्डर में अपलोड होती है; प्रगति वर्कशॉप में दिखती है।",
