"dump_decrypt_risk": "डिक्रिप्ट करने से कंसोल फ़्रीज़ हो सकता है",
"dump_decrypt_risk_body": "डिक्रिप्ट करने के लिए हेल्पर हर एक्ज़ीक्यूटेबल के लिए सिस्टम का वह हिस्सा थोड़ी देर बदलता है जिसे हर प्रोग्राम इस्तेमाल करता है। अगर उसी पल गेम कोई फ़ाइल पढ़े तो कंसोल फ़्रीज़ हो सकता है और ज़बरदस्ती बंद करना पड़ सकता है। इस दौरान गेम की स्टार्ट स्क्रीन पर ही रहें। केवल 13.60 तक का फ़र्मवेयर; नए फ़र्मवेयर पर डंप साधारण कॉपी है।",
